<template>
  <div class="manager-page"><div class="page-heading"><div><div class="eyebrow">CONTENT STUDIO</div><h1>文章管理</h1><p>编辑、发布和维护书院社区内容。</p></div><el-button type="primary" round @click="handleAdd"><el-icon><Plus /></el-icon>发布文章</el-button></div><div class="card table-card"><div class="toolbar"><el-input v-model="query.title" clearable placeholder="搜索文章标题" style="width:260px" @keyup.enter="search"><template #prefix><el-icon><Search /></el-icon></template></el-input><el-select v-model="query.category" clearable placeholder="全部栏目" style="width:150px" @change="search"><el-option v-for="c in categories" :key="c" :label="c" :value="c"/></el-select><div class="grow"></div><span class="text-muted">共 {{total}} 篇文章</span></div><el-table :data="rows" stripe><el-table-column label="文章" min-width="330"><template #default="{row}"><div class="article-cell"><img :src="row.cover"/><div><b>{{row.title}}</b><span>{{row.summary}}</span></div></div></template></el-table-column><el-table-column prop="authorName" label="作者" width="100"/><el-table-column prop="category" label="分类" width="100"/><el-table-column prop="views" label="浏览" width="75"/><el-table-column prop="likes" label="喜欢" width="75"/><el-table-column label="发布时间" width="120"><template #default="{row}">{{date(row.createTime)}}</template></el-table-column><el-table-column label="操作" width="140" align="center"><template #default="{row}"><el-button text type="primary" @click="handleEdit(row)">编辑</el-button><el-button text type="danger" @click="del(row.id)">删除</el-button></template></el-table-column></el-table><div class="pagination-wrap"><el-pagination background layout="prev,pager,next" :total="total" :page-size="query.pageSize" v-model:current-page="query.pageNum" @current-change="load"/></div></div>
<el-dialog v-model="visible" :title="form.id?'编辑文章':'发布文章'" width="760px"><el-form :model="form" label-position="top"><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><div class="form-grid"><el-form-item label="分类"><el-select v-model="form.category" style="width:100%"><el-option v-for="c in categories" :key="c" :label="c" :value="c"/></el-select></el-form-item><el-form-item label="标签"><el-input v-model="form.tags" placeholder="用逗号分隔"/></el-form-item></div><el-form-item label="摘要"><el-input v-model="form.summary" type="textarea" :rows="2"/></el-form-item><el-form-item label="封面"><div class="cover-options"><button v-for="c in covers" :key="c" :class="{selected:form.cover===c}" @click.prevent="form.cover=c"><img :src="c"/></button></div></el-form-item><el-form-item label="正文"><el-input v-model="form.content" type="textarea" :rows="10" placeholder="支持 HTML，也可以输入普通段落"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div>
</template>
<script setup>
import {reactive,ref,computed,onMounted} from 'vue';import request from '@/utils/request';import {ElMessage,ElMessageBox} from 'element-plus'
const user=JSON.parse(localStorage.getItem('system-user')||'{}');const categories=['阅读方法','效率工具','主题书单','教学随笔','技术思考'];const covers=['/images/real/articles/article-01.jpg','/images/real/articles/article-02.jpg','/images/real/articles/article-03.jpg','/images/real/articles/article-04.jpg'];const query=reactive({title:'',category:'',pageNum:1,pageSize:8});const data=reactive({rows:[],total:0});const rows=computed(()=>data.rows),total=computed(()=>data.total),visible=ref(false),form=reactive({});const date=v=>v?String(v).slice(0,10):'';const load=()=>request.get('/article/selectPage',{params:query}).then(res=>{if(res.code==='200'){data.rows=res.data.list||[];data.total=res.data.total||0}});const search=()=>{query.pageNum=1;load()};const reset=()=>Object.assign(form,{id:null,title:'',category:'阅读方法',tags:'',summary:'',cover:covers[0],content:'',userId:user.id,status:'PUBLISHED'});const handleAdd=()=>{reset();visible.value=true};const handleEdit=row=>{reset();Object.assign(form,row);visible.value=true};const save=()=>{request[form.id?'put':'post'](form.id?'/article/update':'/article/add',form).then(res=>{if(res.code==='200'){ElMessage.success('保存成功');visible.value=false;load()}else ElMessage.error(res.msg)})};const del=id=>ElMessageBox.confirm('确认删除该文章？','提示').then(()=>request.delete('/article/delete/'+id).then(()=>{ElMessage.success('已删除');load()}));onMounted(load)
</script>
<style scoped>.article-cell{display:flex;gap:12px;align-items:center}.article-cell img{width:74px;height:48px;border-radius:7px;object-fit:cover}.article-cell div{display:flex;flex-direction:column;gap:5px;min-width:0}.article-cell b{font-size:13px}.article-cell span{font-size:10px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:330px}.cover-options{display:flex;gap:10px}.cover-options button{border:2px solid transparent;background:none;padding:0;border-radius:10px;overflow:hidden;cursor:pointer}.cover-options button.selected{border-color:var(--gold)}.cover-options img{width:110px;height:60px;object-fit:cover;display:block}</style>

